async def act(page):
    # Step 1: Ensure page is fully loaded
    await page.wait_for_load_state("networkidle")

    # Step 2: Navigate directly to the Product Reviews report page using a relative URL
    # (this avoids flaky admin menu clicks). Do not change language settings.
    await page.goto("/index.php/admin/report/review/product/")
    await page.wait_for_load_state("networkidle")

    # Small pause to allow any dynamic content to render
    await page.wait_for_timeout(1000)

    # Step 3: Extract the review count for Apr 2023 using in-page evaluation.
    # Strategy: try several heuristics (global regex, table-row search, element sibling search)
    result = await page.evaluate(r"""() => {
        const bodyText = document.body && document.body.innerText ? document.body.innerText : '';

        // 1) Try a global regex: 'Apr 2023' (or 'April 2023') followed soon after by a number (allow commas)
        let m = bodyText.match(/(?:Apr(?:il)?)[\s.,]*2023[\s\S]{0,200}?([\d,]+)/i);
        if (m) return m[1].replace(/,/g, '');

        // 2) Look through table rows for a cell containing the month and year, then extract the first number after that text
        const monthRegex = /(?:Apr(?:il)?)\s*2023/i;
        const rows = Array.from(document.querySelectorAll('tr'));
        for (const tr of rows) {
            if (monthRegex.test(tr.innerText)) {
                const text = tr.innerText;
                const idx = text.search(monthRegex);
                if (idx >= 0) {
                    const after = text.slice(idx);
                    const mm = after.match(/([\d,]+)/);
                    if (mm) return mm[1].replace(/,/g, '');
                }
                // fallback: any number in the row
                const any = tr.innerText.match(/([\d,]+)/);
                if (any) return any[1].replace(/,/g, '');
            }
        }

        // 3) Find elements that contain 'Apr' and '2023' (maybe split across sibling cells)
        const candidates = Array.from(document.querySelectorAll('td,th,div,span'));
        for (const node of candidates) {
            if (!node.innerText) continue;
            if (/Apr(?:il)?/i.test(node.innerText) && /2023/.test(node.innerText)) {
                // try number in same element
                let mm = node.innerText.match(/([\d,]+)/);
                if (mm) return mm[1].replace(/,/g, '');
            }
            // check next siblings for a number if node mentions Apr or 2023
            if (/Apr(?:il)?/i.test(node.innerText) || /2023/.test(node.innerText)) {
                let sib = node.nextElementSibling;
                while (sib) {
                    const mm = sib.innerText && sib.innerText.match(/([\d,]+)/);
                    if (mm) return mm[1].replace(/,/g, '');
                    sib = sib.nextElementSibling;
                }
            }
        }

        // 4) As a last attempt, search for spelled-out 'April 2023'
        m = bodyText.match(/April\s*2023[\s\S]{0,200}?([\d,]+)/i);
        if (m) return m[1].replace(/,/g, '');

        return null;
    }""")

    # Print the raw extracted value so the harness can capture it exactly.
    # (Do not add additional formatting or text.)
    print(result)

